#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (4) ---
patchFile('siman_020/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The place of shechitah in the neck. In it are 4 seifim. The place of shechitah in the neck is in the trachea on the side toward the head from hat slope downward—and it is before the hat begins to slope and rise—and that is, one must leave some of the wheat grains; and they are at the end of the trachea above, within the large ring, like two grains from the body of the cartilage (meaning: translation of badal ozn—the hardness in the ear cartilage) and they are called wheat grains; and if he slaughtered within the wheat grains and left any amount of them above, it is kosher, for behold he slaughtered from hat slope downward; and if he did not leave any of them but slaughtered above them, behold this is hagramah (meaning: hagramah is the knife's deviation outside the place of shechitah toward the head or toward the body) and it is invalid. {Rama: And l'chatchila one should slaughter below the large ring (Mordechai chapter Eizehu Mekoman and Mahariu laws of shechitah; see s.k. 1).} And its measure below is until the head of the wing of the lung when they inflate it and it rises upward until the place where its head reaches in the trachea—then that is the place itself that it had touched when the animal was alive and was grazing in its normal manner when it stretches its neck to graze, without forcing itself to stretch its neck excessively. {Rama: And in a bird, below in the trachea like the esophagus (Ran in the name of Ra'ah) (see s.k. 4 for the entire seif).}`,
  '2#main': `In the esophagus, the place begins from where when one cuts it, it contracts, until the place where hair begins and it starts to become perforated—if he slaughtered above this place, called the crop of the esophagus, or below this place, which is the beginning of the intestines, his slaughter is invalid. And the measure of the crop of the esophagus that is not fit for shechitah above—in animal and beast—is so that one can grasp it with two fingers. {Rama: And some say: the width of four fingers (Tur in the name of Rashi and Mahariu); and it was received from the ancients that in every animal and beast the measure is until the place where the animal's or beast's ear reaches when they bend it (gloss in Mahariu and Or Zaru'a in the name of some commentaries and Beit Yosef in the name of Mahari Chai).} And in a bird, everything is according to its size, large or small. {Rama: And there is no difference between a dove and other birds—for all of them their measure is equal (agreement of all poskim) (thus proved Darkei Moshe that yonah in the Gemara is a place-name, not a bird—to exclude Beit Yosef in the name of Mahari Chai).} And below until the zefek. {Rama: And a bird that has no zefek—until between the wings (Beit Yosef); and since we are not expert in these measures, it is proper to slaughter in the middle of the neck along its length, for then one exits doubt (Beit Yosef in the name of Semak).}`,
  '3#main': `The slaughterer must slaughter in the middle of the neck; and if he slaughtered from the sides, his slaughter is kosher—provided that he returned the simanim and knows that he cut them before he cut the spinal column, for the simanim are soft and pushed aside by the knife—and the same law applies to one who slaughters from the nape.`,
  '4#main': `It is good to be careful to feel the simanim and grasp them before slaughter so that they present themselves before the flesh of the neck; and in doves the simanim are found on the sides, and hand training and great caution are required—for if he does not feel them and arrange them before him before slaughter, it is very likely he will err and cut the spinal column before the simanim.`,
});

